from speech_client import get_polly_client


def synthesize_ssml(payload, config=None):
    config = config or {}
    client = get_polly_client(region_name=config.get("region"))
    response = client.synthesize_speech(Text=payload["ssml"], TextType="ssml", OutputFormat="mp3",
                                       VoiceId=config.get("voice_id", "Joanna"))
    stream = response["AudioStream"]
    try:
        return {"audio_bytes": stream.read(), "content_type": "audio/mpeg"}
    finally:
        stream.close()

from speech_client import get_polly_client


def select_voice(language_code=None, config=None):
    config = config or {}
    client = get_polly_client(region_name=config.get("region"))
    if language_code:
        response = client.describe_voices(LanguageCode=language_code)
    else:
        response = client.describe_voices()
    voices = [{
        "id": voice["Id"],
        "name": voice["Name"],
        "gender": voice["Gender"],
        "language_code": voice["LanguageCode"]
    } for voice in response["Voices"]]
    return {"voices": voices}

def save_audio(audio_bytes, file_path):
    with open(file_path, "wb") as f:
        f.write(audio_bytes)
    return {"status": "success", "file_path": file_path}

from speech_client import get_translate_client


def script_translate(text, source_language_code, target_language_code, config=None):
    config = config or {}
    client = get_translate_client(region_name=config.get("region"))
    response = client.translate_text(
        Text=text,
        SourceLanguageCode=source_language_code,
        TargetLanguageCode=target_language_code
    )
    return {"translated_text": response["TranslatedText"], "source_language": response["SourceLanguageCode"], "target_language": response["TargetLanguageCode"]}

